// Actions-only real private-bus authenticated IM business send validation.
include!("app_voice_im_send_options_http_tests.rs");
#[tokio::test]async fn im_send_http_routes_require_auth_and_no_caller_uid_scope_token_or_reply(){let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-outbox";for method in [reqwest::Method::GET,reqwest::Method::POST]{let(status,_,body)=account_request(&served,method,path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);}let cookie=authenticate(&served).await;for key in ["uid","scope_epoch","token","reply","index","account","route"]{let mut body=serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"recipient":"1_2","content":"explicit outbound IM","consent":true,"write_consent":true});body[key]=serde_json::json!("fixture-private");let(status,headers,body)=account_request(&served,reqwest::Method::POST,path,Some(body),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}}
#[tokio::test]async fn im_send_http_saved_installation_never_grants_send_without_current_sdk_and_two_consents(){let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let mut config=im_runtime_config_json(&cert.root);config["profile"]["im_send"]=serde_json::json!({"send_text":true,"send_info":true});let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":config})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);for(revision,consent,write_consent,want)in[(1,false,true,StatusCode::FORBIDDEN),(1,true,false,StatusCode::FORBIDDEN),(2,true,true,StatusCode::CONFLICT),(1,true,true,StatusCode::SERVICE_UNAVAILABLE)]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/im-outbox"),Some(serde_json::json!({"expected_revision":revision,"nonce":"a".repeat(32),"recipient":"1_2","content":"explicit body","consent":consent,"write_consent":write_consent})),Some(&cookie)).await;assert_eq!(status,want);no_store(&headers);no_secrets(&body);let failure:serde_json::Value=serde_json::from_str(&body).unwrap();assert_eq!(failure["im_send_admission"],"not_admitted");let mut hash=ring::digest::Context::new(&ring::digest::SHA256);hash.update(b"original-im-send-ui-nonce-v1\0");hash.update("a".repeat(32).as_bytes());let tag:String=hash.finish().as_ref().iter().map(|b|format!("{b:02x}")).collect();assert_eq!(failure["nonce_tag"],tag);assert!(!body.contains(&"a".repeat(32)));}let snapshot=state.app.app_accounts.get(&line,100).await.unwrap();assert!(snapshot.im_send_supported.is_none());assert_eq!(snapshot.phase,"stopped");assert!(!snapshot.outbound_authorized&&!snapshot.incoming_message_ready&&!snapshot.incoming_call_ready);}
#[tokio::test]async fn im_send_http_fields_are_bounded_and_cannot_override_original_account_statistics(){let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-outbox";for extra in [serde_json::json!({"parameters":[{"key":b"account".to_vec(),"value":b"forged-account".to_vec()}]}),serde_json::json!({"notifications":[{"key":b"Statistics.AppId".to_vec(),"value":b"forged-app".to_vec()}]}),serde_json::json!({"info_type":"bad/path"}),serde_json::json!({"nonce":"A".repeat(32)})]{let mut body=serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"recipient":"1_2","content":"explicit outbound body","consent":true,"write_consent":true});for(key,value)in extra.as_object().unwrap(){body[key]=value.clone();}let(status,headers,body)=account_request(&served,reqwest::Method::POST,path,Some(body),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}}
